import { resolve } from 'node:path';
import { pathToFileURL } from 'node:url';
import { SANITY_FUNCTION_DURABLE } from '../../constants.js';
import { isLocalFunctionResource } from '../types.js';
import { findFunctionEntryPoint } from './find-entry-point.js';
import { transpileFunction } from './transpile/function.js';
const DURABLE_CONFIG_KEYS = ['event', 'durableTimeout'];
/**
 * Extracts the blueprint config from the function source code and mutates it to the resource object.
 * This is used for durable functions that may not have a config defined in the blueprint.
 * @param resource
 * @param blueprintFileDir
 */
export const extractDurableConfig = async (resource, blueprintFileDir) => {
    if (!isLocalFunctionResource(resource))
        return;
    // skip if not a durable function
    if (resource.type !== SANITY_FUNCTION_DURABLE)
        return;
    // Check if source needs to be transpiled before attempting to get config
    const resourceSrc = resolve(blueprintFileDir, resource.src);
    const entryPoint = await findFunctionEntryPoint(resourceSrc, resource.name);
    let importPath = entryPoint;
    let cleanup = async () => { };
    // need to transpile and grab the config from the built output if the entry point is a TypeScript file
    if (entryPoint.endsWith('.ts')) {
        const built = await transpileFunction({ resource, functionPath: resourceSrc, entryPoint });
        importPath = await findFunctionEntryPoint(built.outputDir, resource.name);
        cleanup = built.cleanup;
    }
    let config = {};
    try {
        const mod = await import(pathToFileURL(importPath).href);
        config = (mod.handler || mod.default)?.config;
    }
    finally {
        await cleanup();
    }
    // Update values not included in the blueprint, but set in the config
    if (config) {
        if (resource.event === undefined && config.event !== undefined) {
            resource.event = config.event;
        }
        if (resource.durableTimeout === undefined && config.durableTimeout !== undefined) {
            resource.durableTimeout = config.durableTimeout;
        }
    }
};
